<script setup lang="ts">
const props=defineProps<{data:any,previous?:any,compare?:boolean}>(),{t}=useI18n()
const table=ref(false),selected=ref<string|null>(null)
const keys=['day_0_1','day_1_2','day_2_3','day_3_5','day_5_7','day_over_7']
const rows=computed(()=>keys.map(key=>({key,...props.data.buckets[key]})))
const maximum=computed(()=>Math.max(1,...rows.value.map(row=>row.quantity)))
const format=(value:any)=>value==null?'—':Number(value)>0&&Number(value)<.01?'<0.01':Number(value).toLocaleString(undefined,{maximumFractionDigits:2})
const columns=computed(()=>[{key:'key',label:t('putaway-source.duration')},{key:'quantity',label:t('putaway-source.quantity'),type:'qty' as const},{key:'records',label:t('putaway-source.records'),type:'qty' as const}])
watch(()=>props.data,()=>selected.value=null)
</script>
<template><WCard><header><div><h2>{{t('putaway-source.title')}} <small>{{data.known_quantity}} {{t('putaway-source.quantity')}}</small></h2><p>{{t('putaway-source.hint')}}</p></div><WButton size="sm" variant="text" @click="table=!table">{{t(table?'putaway-source.chart':'putaway-source.table')}}</WButton></header>
 <div class="stats"><div v-for="key in ['median_days','p90_days','overdue_quantity']" :key="key"><span>{{t('putaway-source.'+key)}}</span><strong>{{format(data[key])}} <small>{{t(key==='overdue_quantity'?'putaway-source.quantity':'putaway-source.days')}}</small></strong><small v-if="compare&&previous">{{t('putaway-source.previous')}} {{format(previous[key])}}</small></div></div>
 <WAlert v-if="data.unknown_quantity" tone="info" :title="t('putaway-source.unknown-timing',{quantity:data.unknown_quantity})"/>
 <WTable v-if="table" :rows="rows" :columns="columns" row-key="key"><template #cell-key="{row}"><button class="text-link" @click="selected=selected===row.key?null:row.key">{{t('putaway-source.buckets.'+row.key)}}</button></template></WTable>
 <div v-else class="chart" :aria-label="t('putaway-source.title')"><button v-for="(row,index) in rows" :key="row.key" class="bar-column" :aria-pressed="selected===row.key" @click="selected=selected===row.key?null:row.key"><span>{{row.quantity}}</span><div class="track"><i :class="{overdue:index>=3}" :style="{height:(row.quantity/maximum*100)+'%'}"/></div><span>{{t('putaway-source.buckets.'+row.key)}}</span></button></div>
 <div v-if="selected" class="records"><p>{{t('putaway-source.first-records')}}</p><NuxtLink v-for="row in data.buckets[selected].items" :key="row.id" :to="{path:'/inventory/ledger',query:{doc_type:'putaway',doc_id:row.id}}">ASN #{{row.asn_id}} &middot; {{row.quantity}} {{t('putaway-source.quantity')}} &middot; {{format(row.days)}} {{t('putaway-source.days')}}</NuxtLink><WEmptyState v-if="!data.buckets[selected].items.length" :title="t('common.empty')"/></div>
 </WCard></template>
<style scoped>header{display:flex;gap:12px;justify-content:space-between;align-items:start}h2{font-size:16px;font-weight:600;margin:0}h2 small{font-size:13px;font-weight:400;margin-left:8px}p{font-size:13px;color:var(--w-text-3);line-height:20px}small{color:var(--w-text-3)}.stats{display:flex;gap:24px;margin:20px 0}.stats>div{flex:1;border-right:1px solid var(--w-border)}.stats>div:last-child{border:0}.stats span{font-size:13px}.stats strong{display:block;font-size:22px;margin:8px 0}.stats strong small{font-size:12px;font-weight:400}.chart{display:flex;gap:16px;margin-top:24px}.bar-column{background:none;border:0;flex:1;min-width:0;font-size:12px;color:var(--w-text-2);cursor:pointer}.bar-column[aria-pressed=true]{outline:2px solid var(--w-pri);outline-offset:4px}.track{height:130px;display:flex;align-items:end;margin:8px 0;border-bottom:1px solid var(--w-border)}i{display:block;width:100%;background:#9b8afb;min-height:0}i.overdue{background:#e4a768}.records{margin-top:20px;border-top:1px solid var(--w-border)}.records a{display:block;padding:8px 0;color:var(--w-pri)}.text-link{color:var(--w-pri);background:none;border:0;cursor:pointer}@media(max-width:767px){header{flex-wrap:wrap}.chart{gap:8px}.stats{gap:12px}.stats strong{font-size:18px}}</style>
